import { randomUUID } from "node:crypto";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { afterAll, beforeAll, describe, it, expect } from "vitest";
import {
  databaseTestsEnabled,
  createIsolatedDatabase,
} from "./helpers/foundation-db";
import { consumeBudgets, RateLimitError } from "@/lib/rate-limit";
describe.runIf(databaseTestsEnabled)(
  "rolling admissions on independent Postgres clients",
  () => {
    let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>,
      a: PrismaClient,
      b: PrismaClient;
    beforeAll(async () => {
      fixture = await createIsolatedDatabase();
      for (const m of fixture.migrations) await fixture.apply(m);
      a = new PrismaClient({
        adapter: new PrismaPg(
          { connectionString: fixture.url, max: 5 },
          { schema: fixture.schema },
        ),
      });
      b = new PrismaClient({
        adapter: new PrismaPg(
          { connectionString: fixture.url, max: 5 },
          { schema: fixture.schema },
        ),
      });
    });
    afterAll(async () => {
      await a?.$disconnect();
      await b?.$disconnect();
      await fixture?.cleanup();
    });
    it("serializes a simultaneous final-slot race and isolates owners", async () => {
      const owner = randomUUID();
      for (let i = 0; i < 4; i++) await consumeBudgets(owner, ["checkout"], a);
      const results = await Promise.allSettled(
        Array.from({ length: 10 }, (_, i) =>
          consumeBudgets(owner, ["checkout"], i % 2 ? a : b),
        ),
      );
      expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
      for (const r of results)
        if (r.status === "rejected")
          expect(r.reason).toBeInstanceOf(RateLimitError);
      expect(
        (
          await a.rateLimitBucket.findUniqueOrThrow({
            where: { scope_operation: { scope: owner, operation: "checkout" } },
          })
        ).admissions,
      ).toHaveLength(5);
      await expect(
        consumeBudgets(randomUUID(), ["checkout"], b),
      ).resolves.toBeUndefined();
    });
    it("shares management and export budgets and retains failed-operation consumption", async () => {
      const owner = randomUUID();
      await consumeBudgets(owner, ["export"], a);
      await expect(
        a.$transaction(async () => {
          throw new Error("business failed");
        }),
      ).rejects.toThrow();
      await consumeBudgets(owner, ["export"], b);
      await expect(consumeBudgets(owner, ["export"], a)).rejects.toBeInstanceOf(
        RateLimitError,
      );
      for (let i = 0; i < 10; i++)
        await consumeBudgets(owner, ["billingManagement"], i % 2 ? a : b);
      await expect(
        consumeBudgets(owner, ["billingManagement"], b),
      ).rejects.toBeInstanceOf(RateLimitError);
    });
    it("prunes a rolling window and atomically denies multiple admin budgets", async () => {
      const owner = randomUUID();
      await consumeBudgets(owner, ["checkout"], a);
      await a.$executeRaw`UPDATE "RateLimitBucket" SET admissions=ARRAY[clock_timestamp()-interval '10 minutes'] WHERE scope=${owner}`;
      for (let i = 0; i < 5; i++) await consumeBudgets(owner, ["checkout"], a);
      await expect(
        consumeBudgets(owner, ["checkout"], b),
      ).rejects.toBeInstanceOf(RateLimitError);
      for (let i = 0; i < 5; i++)
        await consumeBudgets(
          owner,
          ["admin", "systemActor", "systemGlobal"],
          a,
        );
      await expect(
        consumeBudgets(owner, ["systemGlobal", "admin", "systemActor"], b),
      ).rejects.toBeInstanceOf(RateLimitError);
      const rows = await a.rateLimitBucket.findMany({
        where: { scope: owner, operation: { in: ["admin", "systemActor"] } },
      });
      expect(rows.map((r) => r.admissions.length)).toEqual([5, 5]);
      const other = randomUUID();
      for (let i = 0; i < 5; i++)
        await consumeBudgets(
          other,
          ["admin", "systemActor", "systemGlobal"],
          b,
        );
      await expect(
        consumeBudgets(
          randomUUID(),
          ["admin", "systemActor", "systemGlobal"],
          a,
        ),
      ).rejects.toBeInstanceOf(RateLimitError);
    });
  },
);
